  whatsapp:lpSvg('<path d="M3 21l1.65-4.9A8.5 8.5 0 1 1 8 19.4z"/><path d="M9 10c.5 2 2 3.5 4.2 4.4l1.3-1.2 2 .9c-.3 1.2-1.2 1.9-2.4 1.9C10.8 16 8 13 8 10.3c0-1.1.7-2 1.8-2.3z"/>'),
