async function coursesPage(){let cs=await publicData('courses').then(x=>x.filter(c=>c.status==='published')).catch(()=>[]);return `${topbar()}<section class="section"><div class="eyebrow">Our programs</div><h2>Admission preparation courses</h2><p class="section-sub">Explore available courses and their published batches.</p><div class="grid" style="margin-top:28px">${cs.length?cs.map(courseCard).join(''):'<div class="empty" style="grid-column:1/-1">No published courses are available right now.</div>'}</div></section>${footer()}`}
async function courseDetail(slug){
  const key=decodeURIComponent(slug||'');
  const isAdmin=state.roles.includes('admin');
  let c=await result(sb.from('courses').select('*').eq('id',key).maybeSingle()).catch(()=>null);
  if(!c)c=await result(sb.from('courses').select('*').eq('slug',key).maybeSingle()).catch(()=>null);
  if(!c)c=await result(sb.from('courses').select('*').eq('title',key).maybeSingle()).catch(()=>null);
  if(!c)return `${topbar()}<section class="section"><h2>Course not found</h2><p class="muted">This course may be unpublished or its link may have changed.</p><a href="#courses">Back to courses</a></section>${footer()}`;
  const bs=await publicData('batches').then(x=>x.filter(b=>b.course_id===c.id&&(isAdmin||['published','ongoing'].includes(b.status)))).catch(()=>[]);
  const batchIds=bs.map(b=>b.id);
  const exams=batchIds.length?await result(sb.from('exams').select('id,title,start_time,end_time,duration_minutes,batch_id,status').in('batch_id',batchIds).order('start_time')).then(rows=>rows.filter(e=>isAdmin||e.status==='published')).catch(()=>[]):[];
  const routine=c.routine||c.exam_routine||'';
  return `${topbar()}<section class="section"><a href="#courses" class="muted">← All courses</a><div class="grid" style="grid-template-columns:1.2fr .8fr;margin-top:25px"><div><span class="tag">ADMISSION COURSE</span><h1 style="font:800 38px Manrope">${esc(c.title)}</h1><p class="section-sub">${esc(c.description||'')}</p>${c.detailed_information?`<section class="course-extra"><h2>Course details</h2><div class="rich-text">${esc(c.detailed_information).replaceAll('\n','<br>')}</div></section>`:''}${routine?`<section class="course-extra"><h2>Class & exam routine</h2><div class="rich-text">${esc(routine).replaceAll('\n','<br>')}</div></section>`:''}<section class="course-extra"><h2>Exam routine</h2>${exams.length?`<div class="table-wrap"><table><thead><tr><th>Examination</th><th>Date & time</th><th>Duration</th></tr></thead><tbody>${exams.map(e=>`<tr><td><strong>${esc(e.title)}</strong></td><td>${date(e.start_time)} – ${date(e.end_time)}</td><td>${e.duration_minutes||'—'} min</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">The exam routine will be published here when examinations are scheduled.</p>'}</section><h3>Available batches</h3>${bs.length?bs.map(b=>`<div class="notice-card"><strong>${esc(b.name)}</strong> · ${esc(b.batch_code||'')}<p>${esc(b.description||'')}<br>${date(b.start_date)} – ${date(b.end_date)}</p><button class="btn btn-primary btn-sm" onclick="window.enroll('${b.id}')">Enroll in batch</button></div>`).join(''):'<p class="muted">No published batches are available yet.</p>'}</div><div class="course-card"><div class="course-cover"><img src="${esc(c.thumbnail_path?publicAsset(c.thumbnail_path):asset('coursePoster'))}" onerror="this.style.display='none'"></div><div class="course-content"><h3>${esc(c.title)}</h3><div class="price">${money(c.sale_price??c.price)}</div>${bs.length?`<button class="btn btn-primary" style="width:100%;margin-top:18px" onclick="window.enroll('${bs[0].id}')">Enroll now</button>`:'<p class="muted">Enrollment is not open yet.</p>'}</div></div></div></section>${footer()}`
}

