function authPage(kind){let title={login:'Welcome back',register:'Create your account',forgot:'Reset your password'}[kind];return `<div class="auth-wrap"><aside class="auth-side"><a class="brand" href="#home" style="color:white">${logo()}<span>AdmiRank</span></a><h1>${kind==='register'?'Your next chapter starts here.':'Your admission goals are worth preparing for.'}</h1><p>Join a focused learning environment with model tests, performance tracking and structured admission preparation.</p><a href="#home" style="margin-top:35px;color:#cbd6ed">← Back to website</a></aside><main class="auth-main"><form class="auth-box" id="auth-form"><div style="display:flex;justify-content:flex-end">${themeButton()}</div><a class="brand" href="#home">${logo()}<span>AdmiRank</span></a><h2 style="margin-top:28px">${title}</h2><p>${kind==='login'?'Log in to continue your preparation.':kind==='register'?'Register to access your student dashboard.':'We will email you a password reset link.'}</p>${kind==='register'?`<div class="field"><label>Full name</label><input name="full_name" required placeholder="Enter your full name"></div><div class="field"><label>Phone number</label><input name="phone" placeholder="Enter your phone number"></div>`:''}<div class="field"><label>Email address</label><input type="email" name="email" required placeholder="you@example.com"></div>${kind!=='forgot'?`<div class="field"><label>Password</label><input type="password" name="password" required minlength="6" placeholder="Enter your password"></div>`:''}${kind==='login'?`<div class="auth-links"><a href="#forgot">Forgot password?</a><a href="#register">Create account</a></div>`:kind==='register'?`<div class="auth-links"><span>By registering, you agree to use the platform responsibly.</span><a href="#login">Log in</a></div>`:`<div class="auth-links"><a href="#login">Back to login</a></div>`}<button class="btn btn-primary" type="submit">${kind==='login'?'Log in':kind==='register'?'Create account':'Send reset link'} →</button><div class="divider-text">Secure authentication by Supabase</div></form></main></div>`}
async function submitAuth(form,kind){let fd=new FormData(form),email=fd.get('email'),password=fd.get('password');if(kind==='register'){let {data,error}=await sb.auth.signUp({email,password,options:{data:{full_name:fd.get('full_name'),phone:fd.get('phone')}}});if(error)throw error;toast(data.session?'Account created.':'Check your email to confirm your account.');if(data.session)await loadUser();else go('login')}else if(kind==='login'){let {error}=await sb.auth.signInWithPassword({email,password});if(error)throw error;await loadUser();go('dashboard')}else{let {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname+'#reset'});if(error)throw error;toast('Password reset link sent. Check your email.');go('login')}}
async function loadUser(){let {data:{user}}=await sb.auth.getUser();state.user=user;state.profile=null;state.roles=[];if(user){state.profile=await result(sb.from('profiles').select('*').eq('id',user.id).maybeSingle()).catch(()=>null);state.roles=await result(sb.from('user_roles').select('role').eq('user_id',user.id)).then(x=>x.map(r=>r.role)).catch(()=>[])}}
function shell(content,active='dashboard'){let admin=state.roles.includes('admin'),evalr=state.roles.includes('evaluator');return `<div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#dashboard" style="color:#fff">${logo()}<span>AdmiRank</span></a><div class="side-label">WORKSPACE</div>${navLink('dashboard','Overview','⌂')}${navLink('my-courses','My courses','▣')}${navLink('my-exams','Examinations','✎')}${navLink('results','Results','▤')}${navLink('leaderboard','Leaderboard','♜')}${navLink('profile','My profile','◉')}${admin?`<div class="side-label">ADMINISTRATION</div>${navLink('admin','Admin overview','▦')}${navLink('admin-courses','Courses & batches','▣')}${navLink('admin-payments','Payment verification','৳')}${navLink('admin-questions','Question bank','✎')}${navLink('admin-exams','Exam management','▤')}${navLink('admin-users','Users & assignments','♙')}${navLink('admin-content','Website content','◈')}${navLink('admin-results','Evaluation & results','✓')}`:''}${evalr?`<div class="side-label">EVALUATOR</div>${navLink('evaluator','Assigned scripts','✍')}`:''}<div class="sidebar-bottom"><a class="side-link" href="#home">↗ View website</a><a class="side-link" href="#" id="logout">⇥ Log out</a></div></aside><main class="main-area"><header class="dash-top"><div style="display:flex;align-items:center;gap:12px"><button class="icon-btn mobile-menu" id="menu">☰</button><strong>Student & learning portal</strong></div><div class="right">${themeButton()}<span class="user-label muted">${esc(state.profile?.full_name||state.user?.email||'Account')}</span><div class="avatar">${state.profile?.profile_picture_path?`<img src="${esc(picture(state.profile.profile_picture_path))}" alt="Profile">`:esc((state.profile?.full_name||state.user?.email||'A').slice(0,1).toUpperCase())}</div></div></header><div class="dash-content">${content}</div></main></div>`}
async function dashboard(){let [ens,attempts,results]=await Promise.all([publicData('enrollments').catch(()=>[]),publicData('exam_attempts').catch(()=>[]),publicData('exam_results').catch(()=>[])]);let active=ens.filter(e=>e.status==='active').length;let upcoming=await result(sb.from('exams').select('id,title,start_time,end_time,duration_minutes,status,batch_id').eq('status','published').gte('end_time',new Date().toISOString()).order('start_time').limit(5)).catch(()=>[]);let bIds=ens.map(e=>e.batch_id);let batchRows=bIds.length?await result(sb.from('batches').select('id,name,course_id').in('id',bIds)).catch(()=>[]):[];return shell(`<div class="page-title"><div><h1>Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(state.profile?.full_name||'student')} 👋</h1><p>Here’s what’s happening with your preparation.</p></div><a class="btn btn-primary" href="#my-exams">View examinations →</a></div><div class="stat-grid"><div class="stat-card"><div class="stat-label">Active enrollments</div><strong>${active}</strong><small>Current learning access</small></div><div class="stat-card"><div class="stat-label">Exams attempted</div><strong>${attempts.length}</strong><small>Keep practicing</small></div><div class="stat-card"><div class="stat-label">Published results</div><strong>${results.length}</strong><small>Review your progress</small></div><div class="stat-card"><div class="stat-label">Student ID</div><strong style="font-size:18px">${esc(state.profile?.student_id||'Pending')}</strong><small>AdmiRank identity</small></div></div><section class="panel"><div class="panel-head"><h3>Upcoming examinations</h3><a href="#my-exams" class="muted">See all →</a></div>${upcoming.length?`<div class="table-wrap"><table><thead><tr><th>Examination</th><th>Starts</th><th>Duration</th><th></th></tr></thead><tbody>${upcoming.map(e=>`<tr><td><strong>${esc(e.title)}</strong></td><td>${date(e.start_time)}</td><td>${e.duration_minutes} min</td><td><a class="btn btn-primary btn-sm" href="#exam-info/${e.id}">Open</a></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No upcoming examinations found for your active enrollments.</div>'}</section><section class="panel"><div class="panel-head"><h3>My enrolled batches</h3><a href="#my-courses" class="muted">View courses →</a></div>${batchRows.length?batchRows.map(b=>`<div class="notice-card"><strong>${esc(b.name)}</strong><p>Batch access is ${status('active')}</p></div>`).join(''):'<div class="empty">You have no active enrollments yet. Explore the available courses to get started.</div>'}</section>`)}
async function myCourses(){
  const isAdmin=state.roles.includes('admin');
  if(isAdmin){
    const courses=await publicData('courses').catch(()=>[]);
    const batches=await publicData('batches').catch(()=>[]);
    return shell(`<div class="page-title"><div><h1>My courses</h1><p>As an administrator, you have access to every course and batch.</p></div><a href="#admin-courses" class="btn btn-outline">Manage courses</a></div><div class="grid">${courses.length?courses.map(c=>{const own=batches.filter(b=>b.course_id===c.id);return `<article class="course-card"><div class="course-content"><span class="tag">ADMIN ACCESS · ${esc(c.status||'')}</span><h3>${esc(c.title)}</h3><p>${esc(c.description||'')}</p><p>${own.length} batch(es) · ${own.map(b=>esc(b.name)).join(', ')||'No batch created yet'}</p><a class="btn btn-primary" href="#course/${encodeURIComponent(c.id)}">View course →</a></div></article>`}).join(''):'<div class="empty" style="grid-column:1/-1">No courses found. Add a course from Courses & batches.</div>'}</div>`);
  }
  let ens=await publicData('enrollments').catch(()=>[]);let ids=ens.map(e=>e.batch_id);let bs=ids.length?await result(sb.from('batches').select('*').in('id',ids)).catch(()=>[]):[];let cs=bs.length?await result(sb.from('courses').select('*').in('id',bs.map(b=>b.course_id))).catch(()=>[]):[];
  return shell(`<div class="page-title"><div><h1>My courses</h1><p>Your batch enrollments and access status.</p></div><a href="#courses" class="btn btn-primary">Explore courses</a></div><div class="grid">${ens.length?ens.map(e=>{let b=bs.find(x=>x.id===e.batch_id),c=cs.find(x=>x.id===b?.course_id);return `<article class="course-card"><div class="course-content"><span class="tag">${esc(e.status)}</span><h3>${esc(c?.title||'Course')}</h3><p>${esc(b?.name||'Batch')} · ${esc(b?.batch_code||'')}</p><p>Enrollment: ${date(e.enrolled_at)}<br>Expires: ${date(e.expires_at)}</p>${status(e.status)}</div></article>`}).join(''):'<div class="empty" style="grid-column:1/-1">No enrollments yet. <a href="#courses">Browse courses</a></div>'}</div>`)
}
async function myExams(){let exams=await publicData('exams').catch(()=>[]);let attempts=await publicData('exam_attempts').catch(()=>[]);return shell(`<div class="page-title"><div><h1>Examinations</h1><p>Available exams from your enrolled batches.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Examination</th><th>Type</th><th>Schedule</th><th>Duration</th><th>Status</th><th></th></tr></thead><tbody>${exams.length?exams.map(e=>{let a=attempts.filter(x=>x.exam_id===e.id);return `<tr><td><strong>${esc(e.title)}</strong></td><td>${esc(e.exam_type)}</td><td>${date(e.start_time)}</td><td>${e.duration_minutes} min</td><td>${status(a.at(-1)?.status||e.status)}</td><td><a class="btn btn-primary btn-sm" href="#exam-info/${e.id}">Details</a></td></tr>`}).join(''):'<tr><td colspan="6"><div class="empty">No available examinations.</div></td></tr>'}</tbody></table></div></section>`)}
async function examInfo(id){let e=await result(sb.from('exams').select('*,batches(name)').eq('id',id).maybeSingle()).catch(()=>null);if(!e)return shell('<div class="empty">Examination not found or access is unavailable.</div>');return shell(`<div class="page-title"><div><a href="#my-exams" class="muted">← Examinations</a><h1 style="margin-top:12px">${esc(e.title)}</h1><p>${esc(e.description||'')}</p></div>${status(e.status)}</div><div class="grid" style="grid-template-columns:1.2fr .8fr"><section class="panel"><h3>Instructions</h3><p style="white-space:pre-wrap;line-height:1.8;color:#66748e">${esc(e.instructions||'Read each question carefully. Your answers are saved through the secure examination service.')}</p><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><p>Start time: <strong>${date(e.start_time)}</strong></p><p>End time: <strong>${date(e.end_time)}</strong></p><p>Duration: <strong>${e.duration_minutes} minutes</strong></p><p>Total marks: <strong>${e.total_marks}</strong></p><p>Maximum attempts: <strong>${e.max_attempts}</strong></p></section><section class="panel"><h3>Before you begin</h3><p class="muted" style="line-height:1.7">Ensure a stable internet connection. Do not refresh or close the examination window unnecessarily. Your access and attempt are validated by the server.</p>${state.roles.includes('admin')?`<button class="btn btn-outline" style="width:100%;margin-top:18px" onclick="window.previewExam('${e.id}')">View questions (admin preview) →</button><p class="muted" style="font-size:12px">Admin preview is available regardless of the scheduled start time. It does not create an exam attempt.</p>`:`<button class="btn btn-primary" style="width:100%;margin-top:18px" onclick="window.startExam('${e.id}')">Start / resume exam →</button>`}</section></div>`)}
async function adminExamPreview(id){
  if(!state.roles.includes('admin')){toast('Admin access required.',true);return;}
  const exam=await result(sb.from('exams').select('id,title,description,total_marks').eq('id',id).maybeSingle());
  if(!exam)throw Error('Exam not found or you do not have permission to view it.');
  const questions=await result(sb.from('exam_questions').select('*').eq('exam_id',id).order('question_order'));
  const qids=questions.map(q=>q.id);
  const options=qids.length?await result(sb.from('exam_question_options').select('*').in('exam_question_id',qids).order('display_order')):[];
  const body=questions.length?questions.map((q,i)=>{const opts=options.filter(o=>o.exam_question_id===q.id);return `<article class="notice-card"><div class="tag">QUESTION ${i+1} · ${esc(q.question_type||'')}</div><h3>${esc(q.question_text_snapshot||'')}</h3><p class="muted">Marks: ${esc(q.marks??'—')} · Negative: ${esc(q.negative_marks??0)}</p>${opts.length?`<ol>${opts.map(o=>`<li style="margin:8px 0;${o.is_correct?'font-weight:800;color:var(--success,#16834a)':''}">${esc(o.option_label||'')}. ${esc(o.option_text||'')}${o.is_correct?' ✓ Correct answer':''}</li>`).join('')}</ol>`:''}${q.correct_answer_text_snapshot?`<p><strong>Answer:</strong> ${esc(q.correct_answer_text_snapshot)}</p>`:''}${q.explanation_snapshot?`<p><strong>Explanation:</strong> ${esc(q.explanation_snapshot)}</p>`:''}</article>`}).join(''):'<div class="empty">No questions have been added to this exam yet.</div>';
  $('#app').innerHTML=shell(`<div class="page-title"><div><a href="#exam-info/${id}" class="muted">← Back to exam</a><h1>${esc(exam.title)} — Question preview</h1><p>Admin-only preview. Schedule restrictions do not apply; no student attempt is started.</p></div></div><section class="panel"><div class="panel-head"><h3>${questions.length} questions · ${esc(exam.total_marks??'—')} total marks</h3></div>${body}</section>`,'my-exams');translateUI();
}
async function startExam(id){try{let r=await rpc('start_exam',{p_exam_id:id});let data=Array.isArray(r)?r[0]:r;if(data?.error)throw Error(data.error);let attemptId=data?.attempt_id||data?.id||data?.p_attempt_id;if(!attemptId)throw Error(data?.message||'The server did not return an attempt ID.');state.attempt={id:attemptId,...data};let loaded=await rpc('load_exam_questions',{p_attempt_id:attemptId});let payload=Array.isArray(loaded)?loaded[0]:loaded;state.questions=payload.questions||payload.exam_questions||[];if(!state.questions.length&&Array.isArray(payload))state.questions=payload;state.answers={};(payload.answers||[]).forEach(a=>state.answers[a.exam_question_id]={selected_option_id:a.selected_option_id,written_answer_text:a.written_answer_text,answer_image_path:a.answer_image_path});state.questions.forEach(q=>{if(q.saved_answer)state.answers[q.id]={...(state.answers[q.id]||{}),selected_option_id:q.saved_answer.selected_option_id,written_answer_text:q.saved_answer.written_answer_text,answer_image_path:q.saved_answer.answer_image_path}});await Promise.all(Object.values(state.answers).map(async a=>{if(a?.answer_image_path)a.answer_image_url=await getAnswerSignedUrl(a.answer_image_path)}));state.qIndex=0;state.remaining=Math.max(0,Math.floor((new Date(payload.expires_at||state.attempt.expires_at||Date.now()+3600000)-Date.now())/1000));state.page='exam-run';renderExam();}catch(e){err(e)}}
function renderExam(){
  let q=state.questions[state.qIndex];
  if(!q){toast('No examination questions were returned.',true);go('my-exams');return}
  let opts=q.options||q.exam_question_options||[];
  const saved=state.answers[q.id]||{};
  const savedFilePanel=answerFilePanelMarkup(saved.answer_image_path,saved.answer_image_url);
  $('#app').innerHTML=`<div class="app-shell"><main class="main-area"><header class="dash-top"><strong>${esc(state.exam?.title||'Examination in progress')}</strong><div>${status('in_progress')}</div></header><div class="dash-content"><div class="exam-layout"><section class="panel question-card"><div class="question-number">QUESTION ${state.qIndex+1} OF ${state.questions.length} · ${esc(q.question_type||'mcq').toUpperCase()}</div><div class="question-text">${esc(q.question_text_snapshot||q.question_text||'')}</div>${opts.length?opts.map(o=>`<label class="option ${(saved.selected_option_id===o.id)?'selected':''}"><input type="radio" name="answer" value="${o.id}" ${saved.selected_option_id===o.id?'checked':''}><span><strong>${esc(o.option_label||'')}</strong> ${esc(o.option_text||'')}</span></label>`).join(''):`<div class="field"><label>Your written answer</label><textarea id="written-answer" placeholder="Write your answer here…">${esc(saved.written_answer_text||'')}</textarea></div><div class="answer-upload"><label>Upload answer image/PDF (max 15 MB)<br><input id="answer-file" type="file" accept="image/*,application/pdf"><br><button type="button" class="btn btn-outline btn-sm" id="answer-camera-button" style="margin-top:8px">Take photo with camera</button><input id="answer-camera-file" type="file" accept="image/*" capture="environment" style="display:none"><div id="answer-upload-status" role="status" aria-live="polite" style="margin-top:8px;font-size:13px"></div><div id="answer-file-preview">${savedFilePanel}</div></label><small>Private answer-script storage</small></div>`}<div style="display:flex;justify-content:space-between;gap:12px;margin-top:28px"><button class="btn btn-outline" id="prev-q" ${state.qIndex===0?'disabled':''}>← Previous</button><button class="btn btn-primary" id="next-q">${state.qIndex===state.questions.length-1?'Review answers':'Save & next →'}</button></div></section><aside class="exam-side"><section class="panel"><div class="muted" style="text-align:center;font-weight:700">TIME REMAINING</div><div class="timer" id="timer">--:--</div><div class="question-palette">${state.questions.map((x,i)=>`<button class="qdot ${i===state.qIndex?'current':''} ${state.answers[x.id]?'done':''}" data-q="${i}">${i+1}</button>`).join('')}</div><p class="muted" style="font-size:11px;margin-top:14px">Green indicates an answered question.</p><button class="btn btn-danger" id="submit-exam" style="width:100%;margin-top:12px">Submit examination</button></section></aside></div></div></main></div>`;
  translateUI();
  $$('input[name=answer]').forEach(el=>el.addEventListener('change',async()=>{state.answers[q.id]={...(state.answers[q.id]||{}),selected_option_id:el.value};await saveAnswer(q)}));
  $('#written-answer')?.addEventListener('blur',async e=>{state.answers[q.id]={...(state.answers[q.id]||{}),written_answer_text:e.target.value};await saveAnswer(q)});
  const galleryInput=$('#answer-file'),cameraInput=$('#answer-camera-file'),cameraButton=$('#answer-camera-button');
  if(galleryInput)galleryInput.addEventListener('change',async e=>{await uploadAnswer(q,e.target.files?.[0]);e.target.value=''});
  if(cameraButton&&cameraInput)cameraButton.addEventListener('click',()=>cameraInput.click());
  if(cameraInput)cameraInput.addEventListener('change',async e=>{await uploadAnswer(q,e.target.files?.[0]);e.target.value=''});
  $('#prev-q').onclick=async()=>{try{await saveCurrent();state.qIndex--;renderExam()}catch(e){err(e)}};
  $('#next-q').onclick=async()=>{try{await saveCurrent();if(state.qIndex<state.questions.length-1){state.qIndex++;renderExam()}else toast('Review your answers, then submit when ready.')}catch(e){err(e)}};
  $$('[data-q]').forEach(b=>b.onclick=async()=>{try{await saveCurrent();state.qIndex=Number(b.dataset.q);renderExam()}catch(e){err(e)}});
  $('#submit-exam').onclick=submitExam;
  tickTimer();
}

async function saveAnswer(q){try{let a=state.answers[q.id]||{};await rpc('save_exam_answer',{p_attempt_id:state.attempt.id,p_exam_question_id:q.id,p_selected_option_id:a.selected_option_id||null,p_written_answer_text:a.written_answer_text||null,p_answer_image_path:a.answer_image_path||null});return true}catch(e){err(e);return false}}
async function saveCurrent(){let q=state.questions[state.qIndex];if(q&&$('#written-answer'))state.answers[q.id]={...(state.answers[q.id]||{}),written_answer_text:$('#written-answer').value};if(q){const saved=await saveAnswer(q);if(!saved)throw Error('Your answer could not be saved. Stay on this question and retry before moving on or submitting the exam.')}return true}
function setAnswerUploadStatus(message,isError=false){
  const el=$('#answer-upload-status');
  if(el){el.textContent=message;el.style.color=isError?'#dc2626':'var(--success,#16834a)'}
}
async function getAnswerSignedUrl(path){
  if(!path)return null;
  try{
    const {data,error}=await sb.storage.from('answer-scripts').createSignedUrl(path,3600);
    if(error)throw error;
    return data?.signedUrl||null;
  }catch(e){
    console.warn('Could not create a signed answer-file URL:',e);
    return null;
  }
}
function answerMediaMarkup(path,url,compact=false){
  if(!path)return '';
  if(!url)return '<small class="muted">The file path is saved, but its private preview could not be opened.</small>';
  const isPdf=/\.pdf$/i.test(String(path).split('?')[0]);
  if(isPdf)return `<a class="btn btn-outline btn-sm" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open uploaded PDF ↗</a>`;
  const width=compact?'120px':'100%';
  const height=compact?'110px':'420px';
  return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" title="Open uploaded answer image"><img src="${esc(url)}" alt="Uploaded answer script" loading="lazy" style="display:block;max-width:${width};max-height:${height};width:auto;height:auto;object-fit:contain;border:1px solid var(--line);border-radius:10px;margin-top:8px"></a>`;
}
function answerFilePanelMarkup(path,url){
  if(!path)return '';
  const filename=String(path).split('/').pop();
  return `<div class="notice-card" style="margin-top:10px;padding:12px"><strong>Answer file saved</strong><div class="muted" style="font-size:12px;margin-top:4px">${esc(filename)}</div>${answerMediaMarkup(path,url,true)}<small class="muted" style="display:block;margin-top:7px">You can choose another file or take another photo to replace this answer.</small></div>`;
}
async function prepareAnswerFile(file){
  if(!file)throw Error('No file was selected.');
  if(file.size>15*1024*1024)throw Error('File exceeds 15 MB. Choose a smaller image or PDF.');
  let type=(file.type||'').toLowerCase();
  const ext=(file.name||'').split('.').pop().toLowerCase();
  const extTypes={jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',pdf:'application/pdf',heic:'image/heic',heif:'image/heif',avif:'image/avif'};
  if(!type||type==='application/octet-stream')type=extTypes[ext]||type;
  if(type==='application/pdf'){
    if(file.size>15*1024*1024)throw Error('PDF exceeds 15 MB.');
    return {file,type:'application/pdf',extension:'pdf'};
  }
  if(['image/jpeg','image/png','image/webp'].includes(type)){
    const extension=type==='image/jpeg'?'jpg':type.split('/')[1];
    return {file,type,extension};
  }
  if(type.startsWith('image/')){
    // Mobile devices may return HEIC/HEIF/AVIF. Convert when this browser can decode it.
    try{
      if(!window.createImageBitmap)throw Error('Image conversion is not supported by this browser.');
      const bitmap=await createImageBitmap(file);
      const canvas=document.createElement('canvas');
      canvas.width=bitmap.width;canvas.height=bitmap.height;
      const ctx=canvas.getContext('2d');
      if(!ctx)throw Error('Could not process this image.');
      ctx.drawImage(bitmap,0,0);bitmap.close?.();
      const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.88));
      if(!blob)throw Error('Could not convert this photo to JPG.');
      const converted=new File([blob],`${(file.name||'answer').replace(/\.[^.]+$/,'')}.jpg`,{type:'image/jpeg',lastModified:Date.now()});
      return {file:converted,type:'image/jpeg',extension:'jpg'};
    }catch(e){
      throw Error('This phone selected a HEIC/HEIF or unsupported image. Please change the camera format to JPG, or save/export the photo as JPG and upload it again.');
    }
  }
  throw Error('Unsupported file. Please choose a JPG, PNG, WebP image or PDF.');
}
async function uploadAnswer(q,file){
  if(!file)return;
  const input=$('#answer-file'),cameraInput=$('#answer-camera-file');
  if(input)input.disabled=true;if(cameraInput)cameraInput.disabled=true;
  setAnswerUploadStatus('Preparing your answer file…');
  try{
    const prepared=await prepareAnswerFile(file);
    const uid=state.user?.id,attemptId=state.attempt?.id;
    if(!uid||!attemptId)throw Error('Your exam session could not be verified. Your exam has not been submitted. Please stay on this page and contact the administrator.');
    // Storage policy requires: <auth.uid()>/<attempt_id>/<filename>
    const safeName=(prepared.file.name||`answer.${prepared.extension}`).replace(/[^a-zA-Z0-9._-]/g,'_');
    const path=`${uid}/${attemptId}/${Date.now()}-${safeName}`;
    setAnswerUploadStatus('Uploading… please keep this exam page open.');
    const up=await sb.storage.from('answer-scripts').upload(path,prepared.file,{
      upsert:false,contentType:prepared.type,cacheControl:'3600'
    });
    if(up.error)throw up.error;
    const signedUrl=await getAnswerSignedUrl(path);
    state.answers[q.id]={...(state.answers[q.id]||{}),answer_image_path:path,answer_image_url:signedUrl};
    const saved=await saveAnswer(q);
    if(saved===false)throw Error('The file reached Storage, but its answer record was not saved. The file is not yet attached to your submitted answer. Please retry or contact the administrator.');
    const preview=$('#answer-file-preview');
    if(preview)preview.innerHTML=answerFilePanelMarkup(path,signedUrl);
    setAnswerUploadStatus('Answer file uploaded and linked to this question successfully.');
    toast('Answer file uploaded and saved.');
  }catch(e){
    console.error('Answer upload failed:',e);
    setAnswerUploadStatus(e?.message||'Upload failed. Your exam is still open.',true);
    toast(e?.message||'Answer upload failed. Your exam is still open.',true);
  }finally{
    if(input)input.disabled=false;if(cameraInput)cameraInput.disabled=false;
  }
}
let timerInterval;
function tickTimer(){clearInterval(timerInterval);const update=()=>{let t=state.remaining;let el=$('#timer');if(!el)return;el.textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;if(t<=0){clearInterval(timerInterval);submitExam(true)}else state.remaining--};update();timerInterval=setInterval(update,1000)}
async function submitExam(auto=false){if(!auto&&!confirm('Submit this examination? You may not be able to change your answers afterward.'))return;try{await saveCurrent();await rpc('submit_exam_attempt',{p_attempt_id:state.attempt.id});clearInterval(timerInterval);toast('Examination submitted successfully.');go('results')}catch(e){err(e)}}
